import React, { useCallback } from 'react';
import { usePeriodJobPermissions } from '../../../hooks/usePeriodJobPermissions';
import { PeriodActionPanel } from '../../../components/kt/PeriodActionPanel';
import { ktService } from '../../../services/kt/ktService';
import { PERIOD_JOB_TYPES } from '../../../constants/periodJobTypes';
import { PERIOD_REFERENCE_NO } from '../../../constants/periodProcessReferences';
import { periodProcessStatusLabel } from '../../../utils/periodProcessStatusLabel';

const DanhGiaTyGiaPage: React.FC = () => {
  const { canRun, canPost } = usePeriodJobPermissions('exchange-rate-revaluation');
  const getStatus = useCallback(
    async (m: number, y: number) =>
      periodProcessStatusLabel(await ktService.getExchangeRateRevaluationStatus(m, y)),
    [],
  );

  return (
    <PeriodActionPanel
      testIdPrefix="kt-danh-gia-ty-gia"
      title="Đánh giá lại tỷ giá"
      icon="fa-chart-line"
      runLabel="Đánh giá"
      postLabel="Ghi sổ"
      jobType={PERIOD_JOB_TYPES.ExchangeRateRevaluation}
      referenceNo={PERIOD_REFERENCE_NO.ExchangeRateRevaluation}
      getStatus={getStatus}
      onRun={(m, y) => ktService.runExchangeRateRevaluation(m, y)}
      onPost={(m, y) => ktService.postExchangeRateRevaluation(m, y)}
      runPermitted={canRun}
      postPermitted={canPost}
    />
  );
};

export default DanhGiaTyGiaPage;
